#if defined( __cplusplus )
extern "C" {
#endif

typedef struct regf_file_header regf_file_header_t;

struct regf_file_header
{
	/* The signature
	 * Consists of 4 bytes
	 * Contains: "regf"
	 */
	uint8_t signature[ 4 ];

	/* The primary sequence number
	 * Consists of 4 bytes
	 */
	uint8_t primary_sequence_number[ 4 ];

	/* The secondary sequence number
	 * Consists of 4 bytes
	 */
	uint8_t secondary_sequence_number[ 4 ];

	/* The last modification date and time
	 * Consists of 8 bytes
	 * Contains a filetime
	 */
	uint8_t modification_time[ 8 ];

	/* The major format version
	 * Consists of 4 bytes
	 */
	uint8_t major_format_version[ 4 ];

	/* The minor format version
	 * Consists of 4 bytes
	 */
	uint8_t minor_format_version[ 4 ];

	/* The file type
	 * Consists of 4 bytes
	 */
	uint8_t file_type[ 4 ];

	/* Unknown
	 * Consists of 4 bytes
	 */
	uint8_t unknown1[ 4 ];

	/* The root key offset
	 * Consists of 4 bytes
	 */
	uint8_t root_key_offset[ 4 ];

	/* The hive bins size
	 * Consists of 4 bytes
	 */
	uint8_t hive_bins_size[ 4 ];

	/* Unknown
	 * Consists of 4 bytes
	 */
	uint8_t unknown2[ 4 ];

	/* Unknown
	 * Consists of 64 bytes
	 */
	uint8_t unknown3[ 64 ];

	/* Unknown
	 * Consists of 396 bytes
	 */
	uint8_t unknown4[ 396 ];

	/* The XOR-32 checksum of the previous 508 bytes
	 * Consists of 4 bytes
	 */
	uint8_t checksum[ 4 ];
};

#if defined( __cplusplus )
}
#endif

#endif /* !defined( _REGF_FILE_HEADER_H ) */

