     libcerror_error_t **error )
{
	if( ( log_data == NULL )
	 || ( log_data_size == NULL ) )
	{
		return( -1 );
	}
	*log_data_size = 1536;
	*log_data      = (uint8_t *) memory_allocate(
	                              sizeof( uint8_t ) * *log_data_size );

	if( *log_data == NULL )
	{
		return( -1 );
	}
	if( regf_test_transaction_log_set_header(
	     *log_data,
	     sequence_number,
	     sequence_number,
	     LIBREGF_FILE_TYPE_TRANSACTION_LOG1,
	     4096,
	     error ) != 1 )
	{
		return( -1 );
	}
	memory_set(
	 &( ( *log_data )[ 512 ] ),
	 0,
	 1024 );

	memory_copy(
	 &( ( *log_data )[ 512 ] ),
	 "DIRT",
	 4 );

	( *log_data )[ 516 ] = 0x01;

	memory_set(
	 &( ( *log_data )[ 1024 ] ),
	 marker,
	 512 );

	return( 1 );
}

/* Creates an HvLE transaction log
