{
	uint8_t *entry_data   = NULL;
	uint64_t hash_value_1 = 0;
	uint64_t hash_value_2 = 0;

	if( ( log_data == NULL )
	 || ( log_data_size == NULL ) )
	{
		return( -1 );
	}
	*log_data_size = 1536;
