	if( regf_test_transaction_log_set_header(
	     *log_data,
	     sequence_number,
	     sequence_number,
	     LIBREGF_FILE_TYPE_TRANSACTION_LOG6,
	     4096,
	     error ) != 1 )
	{
		return( -1 );
	}
	memory_set(
	 &( ( *log_data )[ 512 ] ),
	 0,
	 1024 );

	entry_data = &( ( *log_data )[ 512 ] );

	memory_copy(
	 entry_data,
	 "HvLE",
	 4 );

	byte_stream_copy_from_uint32_little_endian(
	 &( entry_data[ 4 ] ),
	 1024 );

	byte_stream_copy_from_uint32_little_endian(
	 &( entry_data[ 12 ] ),
	 sequence_number );

	byte_stream_copy_from_uint32_little_endian(
	 &( entry_data[ 16 ] ),
	 4096 );

	byte_stream_copy_from_uint32_little_endian(
	 &( entry_data[ 20 ] ),
	 1 );

	byte_stream_copy_from_uint32_little_endian(
