	byte_stream_copy_from_uint32_little_endian(
	 &( entry_data[ 44 ] ),
	 512 );

	memory_set(
	 &( entry_data[ 48 ] ),
	 marker,
	 512 );

	if( libregf_transaction_log_calculate_marvin32(
	     &hash_value_1,
	     &( entry_data[ 40 ] ),
	     984,
	     error ) != 1 )
	{
		return( -1 );
	}
	byte_stream_copy_from_uint64_little_endian(
