	return( 1 );
}

/* Writes data to a file
 * Returns 1 if successful or -1 on error
 */
int regf_test_transaction_log_write_file(
     const char *filename,
     const uint8_t *data,
     size_t data_size )
{
	FILE *stream = NULL;

	stream = file_stream_open(
	          filename,
	          FILE_STREAM_BINARY_OPEN_WRITE );

	if( stream == NULL )
	{
		return( -1 );
	}
	if( file_stream_write(
	     stream,
	     data,
	     data_size ) != data_size )
	{
		file_stream_close(
		 stream );

		return( -1 );
	}
	file_stream_close(
	 stream );

	return( 1 );
}

/* Reads data from a file
 * Returns read count or -1 on error
 */
ssize_t regf_test_transaction_log_read_file(
         const char *filename,
         uint8_t *data,
         size_t data_size )
{
	FILE *stream      = NULL;
	size_t read_count = 0;

	stream = file_stream_open(
	          filename,
	          FILE_STREAM_BINARY_OPEN_READ );

	if( stream == NULL )
	{
		return( -1 );
	}
	read_count = file_stream_read(
	              stream,
	              data,
	              data_size );

	file_stream_close(
	 stream );

	return( (ssize_t) read_count );
}

/* Tests the Marvin32 hash implementation
 * Returns 1 if successful or 0 if not
 */
int regf_test_transaction_log_marvin32(
     void )
{
	libcerror_error_t *error = NULL;
	uint8_t data[ 40 ];
	uint64_t hash_value      = 0;
	int data_index           = 0;
	int result               = 0;

	for( data_index = 0;
	     data_index < 40;
	     data_index++ )
	{
		data[ data_index ] = (uint8_t) data_index;
	}
	result = libregf_transaction_log_calculate_marvin32(
	          &hash_value,
	          data,
	          40,
	          &error );

	REGF_TEST_ASSERT_EQUAL_INT(
	 "result",
	 result,
	 1 );

	REGF_TEST_ASSERT_IS_NULL(
	 "error",
	 error );

	REGF_TEST_ASSERT_EQUAL_UINT64(
	 "hash_value",
	 hash_value,
	 (uint64_t) 0x2366e1bab67b6ea3UL );

	return( 1 );

on_error:
	if( error != NULL )
	{
		libcerror_error_free(
		 &error );
	}
	return( 0 );
}

/* Tests DIRT transaction log recovery
 * Returns 1 if successful or 0 if not
 */
int regf_test_transaction_log_recover_dirt(
     void )
{
	libcerror_error_t *error      = NULL;
	libregf_file_header_t *header = NULL;
	uint8_t *hive_data            = NULL;
	size_t hive_data_size         = 0;
	uint8_t *log_data             = NULL;
	size_t log_data_size          = 0;
	uint8_t *recovered_data       = NULL;
	size_t recovered_data_size    = 0;
	uint32_t last_sequence_number = 0;
	int number_of_recovered_pages = 0;
	int result                    = 0;

	result = regf_test_transaction_log_create_hive(
	          &hive_data,
	          &hive_data_size,
	          2,
	          1,
	          &error );

	REGF_TEST_ASSERT_EQUAL_INT(
	 "result",
	 result,
	 1 );

	result = regf_test_transaction_log_create_dirt(
	          &log_data,
	          &log_data_size,
	          2,
	          0xa5,
	          &error );

	REGF_TEST_ASSERT_EQUAL_INT(
	 "result",
	 result,
	 1 );

	result = libregf_transaction_log_recover_data(
	          &recovered_data,
	          &recovered_data_size,
	          &last_sequence_number,
	          &number_of_recovered_pages,
	          hive_data,
	          hive_data_size,
	          log_data,
	          log_data_size,
	          NULL,
	          0,
	          &error );

	REGF_TEST_ASSERT_EQUAL_INT(
	 "result",
	 result,
	 1 );

	REGF_TEST_ASSERT_IS_NULL(
	 "error",
	 error );

	REGF_TEST_ASSERT_EQUAL_SIZE(
	 "recovered_data_size",
	 recovered_data_size,
	 (size_t) 8192 );

	REGF_TEST_ASSERT_EQUAL_UINT32(
	 "last_sequence_number",
	 last_sequence_number,
	 (uint32_t) 2 );

	REGF_TEST_ASSERT_EQUAL_INT(
	 "number_of_recovered_pages",
	 number_of_recovered_pages,
	 1 );

	REGF_TEST_ASSERT_EQUAL_UINT8(
	 "recovered_data[ 4096 ]",
	 recovered_data[ 4096 ],
	 (uint8_t) 0xa5 );

	result = libregf_file_header_initialize(
	          &header,
	          &error );

	REGF_TEST_ASSERT_EQUAL_INT(
	 "result",
	 result,
	 1 );

	result = libregf_file_header_read_data(
	          header,
	          recovered_data,
	          512,
	          &error );

	REGF_TEST_ASSERT_EQUAL_INT(
	 "result",
	 result,
	 1 );

	REGF_TEST_ASSERT_IS_NULL(
	 "error",
	 error );

	libregf_file_header_free(
	 &header,
	 NULL );
	memory_free(
	 recovered_data );
	memory_free(
	 log_data );
	memory_free(
	 hive_data );

	return( 1 );

on_error:
	if( error != NULL )
	{
		libcerror_error_free(
		 &error );
	}
	if( header != NULL )
	{
		libregf_file_header_free(
		 &header,
		 NULL );
	}
	if( recovered_data != NULL )
	{
		memory_free(
		 recovered_data );
	}
	if( log_data != NULL )
	{
		memory_free(
		 log_data );
	}
	if( hive_data != NULL )
	{
		memory_free(
