	 REGF_TEST_TRANSACTION_LOG_HIVE_FILENAME );
	remove(
	 REGF_TEST_TRANSACTION_LOG_LOG1_FILENAME );
	remove(
	 REGF_TEST_TRANSACTION_LOG_LOG2_FILENAME );
	remove(
	 REGF_TEST_TRANSACTION_LOG_OUTPUT_FILENAME );

	memory_free(
	 log_data );
	memory_free(
	 hive_data );

	return( 1 );

on_error:
	if( error != NULL )
	{
		libcerror_error_free(
		 &error );
	}
	if( file != NULL )
	{
		libregf_file_free(
		 &file,
		 NULL );
	}
	remove(
	 REGF_TEST_TRANSACTION_LOG_HIVE_FILENAME );
	remove(
	 REGF_TEST_TRANSACTION_LOG_LOG1_FILENAME );
	remove(
	 REGF_TEST_TRANSACTION_LOG_LOG2_FILENAME );
	remove(
	 REGF_TEST_TRANSACTION_LOG_OUTPUT_FILENAME );

